# Parametri di movimento del giocatore
@export_group("Movement")
@export_range(100.0, 800.0, 10.0, "suffix:px/s") var speed: float = 350.0

# Regole di gioco e bilanciamento
@export_group("Gameplay")
@export_range(1, 10) var max_lives: int = 3
@export_range(3.0, 30.0, 0.5, "suffix:s") var wave_duration: float = 10.0
@export var basket_color: Color = Color.GREEN

# Scene da generare durante la partita
@export_group("Spawning")
@export var item_scene: PackedScene
@export var rock_scene: PackedScene
@export var ruby_scene: PackedScene

@onready var hud: CanvasLayer = $HUD
@onready var shadow: Sprite2D = $Shadow
@onready var indicator: Sprite2D = %Indicator
@onready var restart_button: Button = $RestartButton
@onready var spawn_timer_node: Timer = $SpawnTimer
@onready var wave_timer: Timer = $WaveTimer
@onready var flash_timer: Timer = $FlashTimer

const START_POSITION: Vector2 = Vector2(576, 600)
const MIN_X: float = 64.0
const MAX_X: float = 1088.0
const START_Y: float = 80.0
const SPAWN_MIN_X: float = 64.0
const SPAWN_MAX_X: float = 1088.0
const INITIAL_STARS_COUNT: int = 5
const DIFFICULTY_RAMP_SECONDS: float = 60.0
const SPAWN_INTERVAL_MAX: float = 2.0
const SPAWN_INTERVAL_MIN: float = 0.5
const MAX_SPEED_BOOST: float = 150.0
const SCORE_SPEED_BOOST: float = 10.0
const WIN_SCORE: int = 100
const ROCK_START_X: float = 160.0
const ROCK_END_X: float = 960.0
const ROCK_ROW_Y: float = 200.0
const ROCK_SPACING: float = 200.0

enum GameState { PLAYING, GAME_OVER, PAUSED, WIN }

var current_state: GameState = GameState.PLAYING
var player_name: String = "Cesto"
var lives: int = 3
var score: int = 0
var is_active: bool = true
var current_wave: int = 1
var is_invulnerable: bool = false
var game_time: float = 0.0


func _ready() -> void:
	position = START_POSITION
	lives = max_lives
	modulate = basket_color
	if hud != null:
		hud.update_score(score)
		hud.update_lives(lives)
		hud.update_wave_progress(0.0, wave_duration)
	if spawn_timer_node != null:
		spawn_timer_node.timeout.connect(_on_spawn_timer_timeout)


func _process(delta: float) -> void:
	if current_state != GameState.PLAYING:
		return

	var direction: float = 0.0
	if Input.is_action_pressed("move_left"):
		direction -= 1.0
	if Input.is_action_pressed("move_right"):
		direction += 1.0
	position.x += direction * speed * delta
	position.x = clampf(position.x, MIN_X, MAX_X)

	_check_collisions()


func _check_collisions() -> void:
	var items: Array[Node] = get_tree().get_nodes_in_group("falling_items")
	for item in items:
		if item is FallingItem:
			var fi := item as FallingItem
			if fi.is_caught(position):
				score += fi.points
				score_changed.emit(score)
				if hud != null:
					hud.update_score(score)
				fi.collect()

	var rocks: Array[Node] = get_tree().get_nodes_in_group("rocks")
	for rock in rocks:
		if rock.has_method("check_hit"):
			var dealt_damage: int = rock.call("check_hit", position)
			if dealt_damage > 0:
				take_damage(dealt_damage)


func take_damage(amount: int) -> void:
	if is_invulnerable or current_state != GameState.PLAYING:
		return
	lives -= amount
	lives_changed.emit(lives)
	if hud != null and hud.has_method("update_lives"):
		hud.update_lives(lives)
	if lives <= 0:
		game_over()


func game_over() -> void:
	current_state = GameState.GAME_OVER
	get_tree().change_scene_to_file("res://game_over.tscn")


func _on_spawn_timer_timeout() -> void:
	if item_scene == null or current_state != GameState.PLAYING:
		return
	var item_instance := item_scene.instantiate() as Node2D
	if item_instance != null:
		get_parent().add_child(item_instance)
		if item_instance.has_method("reset_item"):
			item_instance.call("reset_item")


func _on_restart_button_pressed() -> void:
	get_tree().change_scene_to_file("res://basket.tscn")

extends VBoxContainer

@onready var name_input: LineEdit = %NameInput
@onready var difficulty_slider: HSlider = %DifficultySlider
@onready var difficulty_bar: ProgressBar = %DifficultyBar
@onready var warning_label: Label = %WarningLabel
@onready var practice_check: CheckBox = %PracticeCheck
@onready var powerups_check: CheckBox = %PowerupsCheck
@onready var summary_label: Label = %SummaryLabel
@onready var start_button: Button = %StartButton
@onready var reset_button: Button = %ResetButton


func _ready() -> void:
	difficulty_slider.min_value = 1.0
	difficulty_slider.max_value = 5.0
	difficulty_slider.step = 1.0
	difficulty_slider.value = 2.0

	difficulty_bar.min_value = difficulty_slider.min_value
	difficulty_bar.max_value = difficulty_slider.max_value
	difficulty_bar.value = difficulty_slider.value

	warning_label.text = "Attenzione: velocità stelle elevata!"
	warning_label.visible = false

	name_input.placeholder_text = "Inserisci il tuo nome..."
	practice_check.text = "Modalità allenamento"
	powerups_check.text = "Attiva oggetti rari (rubini)"
	start_button.text = "Gioca"
	start_button.disabled = true
	reset_button.text = "Ripristina predefiniti"

	name_input.text_changed.connect(_on_name_input_text_changed)
	difficulty_slider.value_changed.connect(_on_difficulty_slider_value_changed)
	practice_check.toggled.connect(_on_practice_check_toggled)
	powerups_check.toggled.connect(_on_powerups_check_toggled)
	start_button.pressed.connect(_on_start_button_pressed)
	reset_button.pressed.connect(_on_reset_button_pressed)

	_update_summary()


func _on_name_input_text_changed(new_text: String) -> void:
	var trimmed_name: String = new_text.strip_edges()
	start_button.disabled = (trimmed_name == "")
	_update_summary()


func _on_difficulty_slider_value_changed(new_value: float) -> void:
	difficulty_bar.value = new_value
	_update_warning()
	_update_summary()


func _on_practice_check_toggled(toggled_on: bool) -> void:
	if toggled_on:
		difficulty_slider.visible = false
		difficulty_bar.visible = false
		warning_label.visible = false
		powerups_check.button_pressed = true
		powerups_check.disabled = true
	else:
		difficulty_slider.visible = true
		difficulty_bar.visible = true
		powerups_check.disabled = false
		_update_warning()
	_update_summary()


func _on_powerups_check_toggled(_toggled_on: bool) -> void:
	_update_summary()


func _on_start_button_pressed() -> void:
	var settings: Dictionary = get_game_settings()
	Game.player_name = settings["player_name"]
	Game.difficulty = settings["difficulty"]
	Game.reset_session()
	get_tree().change_scene_to_file("res://basket.tscn")


func _on_reset_button_pressed() -> void:
	name_input.text = ""
	practice_check.button_pressed = false
	difficulty_slider.visible = true
	difficulty_bar.visible = true
	difficulty_slider.value = 2.0
	difficulty_bar.value = 2.0
	powerups_check.button_pressed = false
	powerups_check.disabled = false
	start_button.disabled = true
	_update_warning()
	_update_summary()


func _update_warning() -> void:
	if practice_check.button_pressed:
		warning_label.visible = false
	else:
		warning_label.visible = (difficulty_slider.value >= 4.0)


func _update_summary() -> void:
	var player_name_text: String = name_input.text.strip_edges()
	if player_name_text == "":
		player_name_text = "(nessuno)"
	var powerups_text: String = "Sì" if powerups_check.button_pressed else "No"
	var diff_text: String = "1 (Allenamento)" if practice_check.button_pressed else str(int(difficulty_slider.value))
	summary_label.text = "Giocatore: %s | Difficoltà: %s | Oggetti rari: %s" % [player_name_text, diff_text, powerups_text]


func get_game_settings() -> Dictionary:
	var final_difficulty: int = 1 if practice_check.button_pressed else int(difficulty_slider.value)
	return {
		"player_name": name_input.text.strip_edges(),
		"difficulty": final_difficulty,
		"powerups": powerups_check.button_pressed,
		"practice_mode": practice_check.button_pressed,
	}

